// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g1, bytes32 g2) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, 2 ether);

        // first round: lock in a guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g1);

        // advance past the target block and settle
        vm.roll(block.number + 2);
        vm.prank(actor);
        c.settle();

        // general rule: after settle, the actor may lock in a new guess.
        // Reference resets guesses[actor].block to 0, so this succeeds.
        // Mutant leaves block != 0, so this always reverts.
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(g2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "settled actor must be able to lock in a new guess");
    }
}
